"""Compose docs/MODEL_VALIDATION.md from data/validation/*.json (written by audit_model.py and model_harness.py) and data/recon/*.json (reconcile.py).
Nothing is typed by hand: every number below is read from the latest run artefacts."""
import glob, json, os, re
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
V = os.path.join(R, "data", "validation")
out = ["# Model validation\n",
       "Generated by `scripts/validation_report.py` from the artefacts of the latest runs: `npm run model:audit` (`data/validation/audit_*.json`), `npm run model:harness:all` "
       "(`data/validation/harness_*.json`, the structured change-impact report with assumptions changed, outputs before/after, expectation and result), `npm run model:reconcile` (`data/recon/*.json`). "
       "Recalculation engine: LibreOffice headless. Unit tests: `npm test` (vitest). Real-data verification: `npm run data:verify`.\n"]
tot = 0
out.append("## Summary\n\n| Case | Audit checks | Excel ⇄ web metrics | Change-impact tests | Workbook unchanged by tests |\n|---|---|---|---|---|")
rows = []
for c in ("amcx", "bdn", "brightwater"):
    a = json.load(open(os.path.join(V, f"audit_{c}.json")))
    ok = sum(x["ok"] for x in a["checks"]); tot += len(a["checks"])
    rc = json.load(open(os.path.join(R, "data", "recon", f"{c}.json")))
    hp = os.path.join(V, f"harness_{c}.json")
    h = json.load(open(hp)) if os.path.exists(hp) else None
    rows.append(f"| {c.upper()} | {ok}/{len(a['checks'])} | {rc['pass_count']}/{rc['total']} | " + (f"{h['tests_passed']}/{h['tests_total']} | {'yes (SHA-256 identical before and after)' if h['workbook_unchanged'] else 'NO'} |" if h else "not run | — |"))
out += rows
out.append(f"\n**Total audit checks: {tot}.**\n")
for c in ("amcx", "bdn", "brightwater"):
    hp = os.path.join(V, f"harness_{c}.json")
    if not os.path.exists(hp):
        continue
    h = json.load(open(hp))
    out.append(f"\n## Change-impact harness — `{c}` ({h['tests_passed']}/{h['tests_total']} pass)\n")
    out.append(f"Each test edits a throw-away copy of `{h['workbook']}`, recalculates in LibreOffice and asserts direction and (where the maths gives an exact answer) size. Committed workbook SHA-256 before = after: `{h['sha256_before'][:16]}…`. Full detail per test (cells changed, before/after outputs) is in `data/validation/harness_{c}.json`.\n")
    out.append("| ID | Test | Result | Observed |\n|---|---|---|---|")
    for t in h["tests"]:
        out.append(f"| {t['id']} | {t['name'].replace('|', '/')} | {t['status']} | {str(t['detail']).replace('|', '/')[:230]} |")
for f in sorted(glob.glob(os.path.join(V, "audit_*.json"))):
    d = json.load(open(f)); ch = d["checks"]; ok = sum(c["ok"] for c in ch)
    out.append(f"\n## Audit — `{d['case']}` ({d['formulas']:,} formulas, {d['inputs']} blue inputs): {ok}/{len(ch)} checks pass\n")
    out.append("| Check | Result | Detail |\n|---|---|---|")
    for c in ch:
        det = str(c["detail"]).replace("|", "/")[:200]
        out.append(f"| {re.sub(r'^\[\w+\] ', '', c['name'])} | {'PASS' if c['ok'] else 'FAIL'} | {det} |")
open(os.path.join(R, "docs", "MODEL_VALIDATION.md"), "w").write("\n".join(out) + "\n")
print("wrote docs/MODEL_VALIDATION.md, audit checks:", tot)
